                    if buy_book[0][3] == 0:
                        buy_book.pop(0)
                        # Update indices for remaining buy orders
                        for i in range(len(buy_book)):
                            oid = buy_book[i][2]
                            if oid in order_map:
                                order_map[oid] = ('buy', i)
                        del order_map[buy_id]
                # Market: remainder is discarded

    return trades
